import json
from pathlib import Path
from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse, HTMLResponse
from fastapi.staticfiles import StaticFiles

ROOT = Path(__file__).parent
RESULTS = ROOT / "results"
app = FastAPI(title="KRAS confidence report")

@app.get("/", response_class=HTMLResponse)
def index():
    return HTML

@app.get("/api/results")
def results():
    return json.loads((RESULTS / "results.json").read_text(encoding="utf-8"))

@app.get("/api/structure/{filename}")
def structure(filename: str):
    if filename not in {"kras_alphafold_model.pdb", "kras_alphafold_model.cif"}:
        raise HTTPException(404)
    path = RESULTS / filename
    if not path.is_file(): raise HTTPException(404)
    return FileResponse(path)

@app.get("/api/pae")
def pae():
    path = ROOT / "data" / "KRAS_alphafold_pae.json"
    return json.loads(path.read_text(encoding="utf-8"))

HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KRAS confidence report</title><script src="https://cdn.tailwindcss.com"></script><script src="https://3dmol.csb.pitt.edu/build/3Dmol-min.js"></script><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body class="bg-slate-950 text-slate-100"><main class="max-w-7xl mx-auto p-5 md:p-8"><header class="mb-6"><p class="text-cyan-300 text-sm font-semibold tracking-wide uppercase">Structure reliability report</p><h1 class="text-3xl md:text-4xl font-bold mt-2">KRAS pocket-region confidence</h1></header><section id="summary" class="grid md:grid-cols-3 gap-4 mb-6"></section><div class="grid lg:grid-cols-2 gap-6"><section class="bg-slate-900 rounded-2xl p-5 border border-slate-800"><h2 class="text-xl font-semibold mb-3">3D model</h2><p class="text-slate-400 text-sm mb-3">Cα model coloured by pLDDT; highlighted residues are the three regions in the specification.</p><div id="viewer" class="relative w-full h-[480px] min-h-[480px] rounded-xl bg-black overflow-hidden"></div><div class="flex flex-wrap items-center gap-3 mt-3 text-xs text-slate-400"><label class="flex items-center gap-2"><span>Colour</span><select id="colourMode" class="bg-slate-800 text-slate-100 rounded px-2 py-1"><option value="raw">Raw pLDDT</option><option value="trust">Trust / amber / don't-trust</option></select></label><span class="text-blue-300">● P-loop</span><span class="text-orange-300">● Switch I</span><span class="text-fuchsia-300">● Switch II</span></div><div id="residueInfo" class="mt-3 min-h-8 rounded-lg bg-slate-800 px-3 py-2 text-sm text-slate-300">Click a residue to inspect its exact pLDDT.</div></section><section class="bg-slate-900 rounded-2xl p-5 border border-slate-800"><h2 class="text-xl font-semibold mb-1">Claim-matched confidence</h2><p class="text-slate-400 text-sm mb-4">Per-residue pLDDT for fold/region reliability. Higher is better.</p><canvas id="chart"></canvas><div id="stats" class="mt-4 grid grid-cols-3 gap-2"></div></section></div><section class="mt-6 bg-slate-900 border border-slate-800 rounded-2xl p-5"><h2 class="text-xl font-semibold">Sequence mismatch audit</h2><p class="text-slate-400 text-sm mt-1 mb-3">Model sequence versus the supplied assay FASTA; differences and model overhang are highlighted.</p><div id="sequenceAudit" class="overflow-auto text-xs font-mono"></div></section><section class="mt-6 bg-amber-950/40 border border-amber-700/60 rounded-2xl p-5"><h2 class="font-semibold text-amber-200 flex gap-2 items-center"><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 9v4m0 4h.01"/><path d="M10.3 3.8 2.2 18a2 2 0 0 0 1.7 3h16.2a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0Z"/></svg>Important caveat</h2><p id="caveat" class="text-amber-100 mt-2"></p></section><footer class="text-slate-500 text-xs mt-6">Provisional model-reliability/design guidance — not evidence of compound binding.</footer></main><script>
const colors={"P-loop":"#60a5fa","Switch I":"#fb923c","Switch II":"#e879f9"};
async function load(){const d=await fetch('/api/results').then(r=>r.json());document.querySelector('#summary').innerHTML=`<div class="md:col-span-2 bg-cyan-950/50 border border-cyan-700/60 rounded-2xl p-5"><p class="text-cyan-300 text-sm">Headline answer</p><h2 class="text-2xl font-bold mt-1">${d.headline}</h2><p class="mt-2 text-cyan-100">${d.recommendation}</p></div><div class="bg-slate-900 border border-slate-800 rounded-2xl p-5"><p class="text-slate-400 text-sm">Structure check</p><p class="mt-2">${d.structure_check}</p><p class="text-slate-400 text-sm mt-3">${d.assembly}</p></div>`;document.querySelector('#caveat').textContent=d.caveat;
const labels=[],vals=[],bg=[];d.regions.forEach(r=>r.values.forEach((v,i)=>{labels.push(String(r.start+i));vals.push(v);bg.push(colors[r.name])}));new Chart(document.getElementById('chart'),{type:'bar',data:{labels,datasets:[{data:vals,backgroundColor:bg,borderWidth:0}]},options:{plugins:{legend:{display:false}},scales:{x:{title:{display:true,text:'Residue number',color:'#94a3b8'},ticks:{color:'#94a3b8'}},y:{min:50,max:100,title:{display:true,text:'pLDDT',color:'#94a3b8'},ticks:{color:'#94a3b8'},grid:{color:'#334155'}}}}});document.querySelector('#stats').innerHTML=d.regions.map(r=>`<div class="rounded-lg p-3 bg-slate-800"><b style="color:${colors[r.name]}">${r.name}</b><br><span class="text-xs text-slate-400">median / mean / min</span><br>${r.median.toFixed(2)} / ${r.mean.toFixed(2)} / ${r.min.toFixed(2)}</div>`).join('');
const viewerElement=document.getElementById('viewer');let viewer=$3Dmol.createViewer(viewerElement,{backgroundColor:'black',width:'100%',height:'100%'});const pdb=await fetch('/api/structure/'+d.structure_file).then(r=>r.text());viewer.addModel(pdb,'pdb');const residueColors={10:'#60a5fa',11:'#60a5fa',12:'#60a5fa',13:'#60a5fa',14:'#60a5fa',15:'#60a5fa',16:'#60a5fa',17:'#60a5fa'};function rawColor(b){return b>=90?'#087f3e':b>=80?'#9acd32':b>=70?'#f59e0b':'#b91c1c'}function trustColor(b){return b>=90?'#16a34a':b>=70?'#f59e0b':'#dc2626'}function colourModel(){const mode=document.getElementById('colourMode').value;viewer.setStyle({}, {cartoon:{colorfunc:a=>mode==='raw'?rawColor(a.b):trustColor(a.b)}});viewer.setStyle({resi:'10-17'},{cartoon:{color:'#2563eb'},stick:{color:'#60a5fa',radius:.18}});viewer.setStyle({resi:'30-38'},{cartoon:{color:'#f97316'},stick:{color:'#fb923c',radius:.18}});viewer.setStyle({resi:'59-76'},{cartoon:{color:'#d946ef'},stick:{color:'#e879f9',radius:.18}});viewer.setStyle({resi:'170-189'},{cartoon:{color:'#475569'}});viewer.render()}colourModel();document.getElementById('colourMode').onchange=colourModel;viewer.setClickable({},true,(atom)=>{document.getElementById('residueInfo').innerHTML=`<b>Residue ${atom.resi} ${atom.resn||''}</b> — exact pLDDT/B-factor: <b>${Number(atom.b).toFixed(2)}</b>`});viewer.zoomTo({chain:'A'});viewer.render();
const fasta=`MTEYKLVVVGADGVGKSALTIQLIQNHFVDEYDPTIEDSYRKQVVIDGETCLLDILDTAGQEEYSAMRDQYMRTGEGFLCVFAINNTKSFEDIHHYREQIKRVKDSEDVPMVLVGNKCDLPSRTVDTKQAQDLARSYGIPFIETSAKTRQRVEDAFYTLVREIRQYRLK`;const model=`MTEYKLVVVGAGGVGKSALTIQLIQNHFVDEYDPTIEDSYRKQVVIDGETCLLDILDTAGQEEYSAMRDQYMRTGEGFLCVFAINNTKSFEDIHHYREQIKRVKDSEDVPMVLVGNKCDLPSRTVDTKQAQDLARSYGIPFIETSAKTRQRVEDAFYTLVREIRQYRLKKISKEEKTPGCVKIKKCIIM`;let rows='<table class="w-full"><tr><th class="text-left p-2">Position</th><th class="text-left p-2">Model</th><th class="text-left p-2">Assay FASTA</th></tr>';for(let i=0;i<Math.max(model.length,fasta.length);i++){let a=model[i]||'—',b=fasta[i]||'—',diff=a!==b;rows+=`<tr class="${diff?'bg-amber-900/60':''}"><td class="p-2 text-slate-400">${i+1}</td><td class="p-2 ${i>=fasta.length?'text-amber-300':''}">${a}</td><td class="p-2 ${i>=fasta.length?'text-slate-600':''}">${b}</td></tr>`}document.getElementById('sequenceAudit').innerHTML=rows+'</table>';}
load();</script></body></html>'''
